/**
 * Self-synthesised background music (generated by FFmpeg `aevalsrc` at render time).
 * Because it is generated from simple math, it carries no third-party licensing risk.
 */
export type MusicStyle = "none" | "calm" | "upbeat";

/** aevalsrc expression for a mono bed. Commas are inside single quotes in the filtergraph. */
export function musicExpression(style: Exclude<MusicStyle, "none">): string {
  if (style === "calm") {
    // A-minor pad with slow swell
    return "0.045*(sin(2*PI*220*t)+0.8*sin(2*PI*261.63*t)+0.7*sin(2*PI*329.63*t))*(0.6+0.4*sin(2*PI*0.2*t))";
  }
  // Upbeat: plucked C-major/A-minor alternation on 120 bpm eighth notes
  return "0.07*exp(-7*mod(t,0.25))*(sin(2*PI*(if(lt(mod(t,4),2),261.63,220))*t)+0.6*sin(2*PI*(if(lt(mod(t,4),2),329.63,261.63))*t)+0.5*sin(2*PI*392*t))+0.05*exp(-30*mod(t,0.5))*sin(2*PI*55*t)";
}

/** Filtergraph snippet producing `[label]` of `durationSec` with fade in/out. */
export function musicFilter(style: Exclude<MusicStyle, "none">, durationSec: number, label: string): string {
  const d = durationSec.toFixed(3);
  const fadeOut = Math.max(0, durationSec - 1.2).toFixed(3);
  return `aevalsrc='${musicExpression(style)}':s=44100:d=${d},aformat=sample_fmts=fltp:channel_layouts=stereo,afade=t=in:d=0.6,afade=t=out:st=${fadeOut}:d=1.2[${label}]`;
}
